import {DrawingHistory} from './drawing-history.js';
import {installCanvasPresentation,exportCanvas,downloadBlob} from './canvas-presentation.js';
export function initCartesianEditor(apply){
 const anchor=document.getElementById('revStudio'),section=document.createElement('details');section.className='rev-cartesian-editor';
 section.innerHTML='<summary>Dibujar en el plano cartesiano</summary><p>Coordenadas en centímetros. Haz clic para añadir puntos; arrastra un punto para moverlo. El eje vertical x = 0 es el eje de giro. La distancia al eje es x.</p><div class="rev-editor-tools"><label>Tipo<select id="revDrawType"><option value="trace">Línea quebrada abierta</option><option value="bezier">Curva Bézier (4 controles)</option><option value="custom">Polígono cerrado</option></select></label><label><input type="checkbox" id="revSnap" checked> Ajustar a 0,25 cm</label><button type="button" id="revUndoPoint">Quitar último punto</button><button type="button" id="revClearPoints">Limpiar</button><button type="button" id="revFitDrawing">Encuadrar</button><button type="button" id="revApplyDrawing" class="primary-btn">Generar revolución</button></div><canvas id="revCartesianCanvas" tabindex="0" aria-label="Editor cartesiano: clic añade un punto y arrastrar mueve un punto"></canvas><p id="revPointerCoordinates" role="status">x = 0 cm; y = 0 cm</p><div id="revEditorPoints"></div><p id="revEditorError" role="alert"></p><p>También puedes corregir cada coordenada en los campos de abajo. Una Bézier utiliza inicio, dos controles y final. Para volumen, el polígono debe ser simple y no cruzar el eje. El borrador no modifica el sólido hasta pulsar Generar revolución.</p>';
 anchor.before(section);const $=id=>document.getElementById(id),canvas=$('revCartesianCanvas'),ctx=canvas.getContext('2d');let points=[[1,-3],[4,-1],[2,1],[3,3]],drag=-1,span=12,w=600,h=400,dirty=false;
 let centerX=0,centerY=0,panStart=null;
 let selected=-1;
 const snapshot=()=>({points:points.map(p=>[...p]),kind:$('revDrawType').value});
 const history=new DrawingHistory(snapshot());
 $('revUndoPoint').textContent='↶ Deshacer';$('revUndoPoint').title='Deshacer (Ctrl+Z)';
 $('revUndoPoint').insertAdjacentHTML('afterend','<button type="button" id="revRedoPoint" title="Rehacer (Ctrl+Y o Ctrl+Mayús+Z)">↷ Rehacer</button><button type="button" id="revDeleteSelected" title="Eliminar punto seleccionado (Supr)">Eliminar punto</button>');
 function syncHistory(){ $('revUndoPoint').disabled=!history.canUndo;$('revRedoPoint').disabled=!history.canRedo;$('revDeleteSelected').disabled=selected<0||selected>=points.length }
 function commit(){history.push(snapshot());syncHistory()}
 function restore(value){points=value.points;$('revDrawType').value=value.kind;selected=-1;dirty=true;draw();table();syncHistory();$('revEditorError').textContent='Borrador restaurado. Pulsa Generar revolución para aplicarlo al sólido.'}
 const map=([x,y])=>[w/2+(x-centerX)*w*.85/span,h/2-(y-centerY)*w*.85/span],unmap=(x,y)=>[centerX+(x-w/2)*span/(w*.85),centerY+(h/2-y)*span/(w*.85)];
 section.querySelector('.rev-editor-tools').insertAdjacentHTML('afterbegin','<label>Herramienta<select id="revEditorTool"><option value="draw">Dibujar / mover puntos</option><option value="pan">Mover plano</option><option value="axis">Mover eje de giro</option></select></label><button id="revEditorZoomIn">+</button><button id="revEditorZoomOut">−</button><button id="revEditorOrigin">Centrar O</button><button id="revEditorFull">⛶ Ampliar editor</button>');
 section.querySelector('p').textContent='Plano cartesiano en centímetros, con valores positivos y negativos. Elige una herramienta: dibujar puntos, mover el plano o desplazar el eje vertical x = a. La rueda amplía o reduce sin mover el punto bajo el cursor.';
 $('revEditorTool').insertAdjacentHTML('beforeend','<option value="select">Seleccionar / mover punto</option>');
 section.querySelector('.rev-editor-tools').insertAdjacentHTML('beforeend','<button type="button" id="revEditorPng">Exportar plano PNG</button><button type="button" id="revEditorSvg">Exportar trazado SVG</button>');
 $('revEditorPoints').insertAdjacentHTML('beforebegin','<details class="rev-direct-points"><summary>Ingresar coordenadas directamente</summary><p>Escribe pares x,y separados por punto y coma o saltos de línea. Ejemplo: 1,-2; 3,0; 2,4. Elige arriba línea quebrada, Bézier o polígono; los polígonos se cierran automáticamente.</p><textarea id="revBulkPoints" rows="3" placeholder="1,-2; 3,0; 2,4" aria-label="Lista de coordenadas"></textarea><button type="button" id="revLoadPoints">Cargar puntos al borrador</button><button type="button" id="revCopyPoints">Llevar dibujo a la lista</button></details>');
 $('revLoadPoints').addEventListener('click',()=>{const parsed=$('revBulkPoints').value.trim().split(/[;\n]+/).filter(s=>s.trim()).map(s=>s.trim().split(',').map(v=>v.trim()===''?NaN:Number(v)));const max=$('revDrawType').value==='custom'?20:$('revDrawType').value==='bezier'?4:40,min=$('revDrawType').value==='custom'?3:$('revDrawType').value==='bezier'?4:2;if(parsed.length<min||parsed.length>max||parsed.some(p=>p.length!==2||p.some(v=>!Number.isFinite(v)||Math.abs(v)>200))){$('revEditorError').textContent=`Escribe de ${min} a ${max} pares x,y entre −200 y 200.`;return}points=parsed;selected=-1;changed();$('revFitDrawing').click()});
 $('revCopyPoints').addEventListener('click',()=>{$('revBulkPoints').value=points.map(p=>p.join(',')).join('; ')});
 $('revEditorPng').addEventListener('click',()=>{draw();exportCanvas(canvas,'plano-cartesiano.png')});
 $('revEditorSvg').addEventListener('click',()=>{
  if(!points.length){$('revEditorError').textContent='Añade puntos antes de exportar.';return}
  const coords=points.map(map),escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');let path=coords.map(([x,y],i)=>`${i?'L':'M'}${x},${y}`).join(' ');
  if($('revDrawType').value==='custom')path+=' Z';if($('revDrawType').value==='bezier'&&coords.length===4)path=`M${coords[0]} C${coords[1]} ${coords[2]} ${coords[3]}`;
  const axis=Number(document.getElementById('revAxisPosition').value),axisX=map([axis,0])[0],svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}"><title>Trazado cartesiano en centímetros</title><metadata>${escape(JSON.stringify({unit:'cm',points,type:$('revDrawType').value,axisX:axis}))}</metadata><rect width="100%" height="100%" fill="white"/><path d="M${axisX} 0V${h}" stroke="#b54913" stroke-width="2"/><path d="${path}" fill="${$('revDrawType').value==='custom'?'#dbeafe':'none'}" stroke="#173d9e" stroke-width="3"/>${coords.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="5" fill="#173d9e"/><text x="${x+9}" y="${y-9}" font-family="Arial" font-size="14">P${i+1}</text>`).join('')}</svg>`;downloadBlob(new Blob([svg],{type:'image/svg+xml'}),'trazado-cartesiano.svg');
 });
 installCanvasPresentation(section,canvas,draw);
 section.querySelector('.rev-editor-tools').insertAdjacentHTML('afterend','<p class="rev-editor-shortcuts">Ctrl+Z: deshacer · Ctrl+Y: rehacer · Supr: eliminar selección · Flechas: mover el punto seleccionado 0,25 cm (Mayús: 1 cm). Los cambios se aplican al borrador.</p>');
 function table(){const root=$('revEditorPoints');root.innerHTML=points.map(([x,y],i)=>`<label>P${i+1}<input type="number" step="0.25" min="-200" max="200" value="${x}" data-point="${i}" data-coordinate="0" aria-label="Punto ${i+1}, coordenada x"><input type="number" step="0.25" min="-200" max="200" value="${y}" data-point="${i}" data-coordinate="1" aria-label="Punto ${i+1}, coordenada y"></label>`).join('')}
 function draw(){if(!section.open)return;const rect=canvas.getBoundingClientRect();if(!rect.width)return;w=rect.width;h=rect.height;const ratio=Math.min(devicePixelRatio,2);canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);const step=span>30?5:span>15?2:1,ys=unmap(0,h)[1],ye=unmap(0,0)[1];ctx.font='12px Arial';ctx.textAlign='center';
  for(let x=Math.ceil(unmap(0,0)[0]/step)*step;x<=unmap(w,0)[0];x+=step){const [px,py]=map([x,0]);ctx.strokeStyle=x===0?'#172033':'#e3e7ed';ctx.lineWidth=x===0?2:1;ctx.beginPath();ctx.moveTo(px,0);ctx.lineTo(px,h);ctx.stroke();ctx.fillStyle='#344155';ctx.fillText(String(x),px,Math.max(15,Math.min(h-5,py+16)))}
  for(let y=Math.ceil(ys/step)*step;y<ye;y+=step){const [px,py]=map([0,y]);ctx.strokeStyle=y===0?'#172033':'#e3e7ed';ctx.lineWidth=y===0?2:1;ctx.beginPath();ctx.moveTo(0,py);ctx.lineTo(w,py);ctx.stroke();if(y)ctx.fillText(String(y),px-18,py+4)}
  ctx.fillStyle='#172033';ctx.textAlign='left';ctx.fillText('y (cm)',8,18);ctx.fillText('x (cm)',w-55,Math.max(18,Math.min(h-8,map([0,0])[1]-8)));const axis=Number(document.getElementById('revAxisPosition')?.value||0),ax=map([axis,0])[0];ctx.strokeStyle='#b54913';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(ax,0);ctx.lineTo(ax,h);ctx.stroke();ctx.fillStyle='#923b0e';ctx.fillText(`eje x = ${axis}`,Math.max(5,Math.min(w-110,ax+8)),35);const o=map([0,0]);ctx.fillStyle='#172033';ctx.fillText('O',o[0]+7,o[1]-8);
  if(points.length){ctx.beginPath();points.forEach((p,i)=>{const [x,y]=map(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});if($('revDrawType').value==='custom'&&points.length>2){ctx.closePath();ctx.fillStyle='#dbeafe';ctx.fill()}ctx.strokeStyle='#9a4c0b';ctx.lineWidth=2;ctx.stroke();if($('revDrawType').value==='bezier'&&points.length===4){ctx.beginPath();const p=points.map(map);ctx.moveTo(...p[0]);ctx.bezierCurveTo(...p[1],...p[2],...p[3]);ctx.strokeStyle='#254eb0';ctx.lineWidth=3;ctx.stroke()}points.forEach((p,i)=>{const [x,y]=map(p);ctx.beginPath();ctx.arc(x,y,7,0,2*Math.PI);ctx.fillStyle='#283fa4';ctx.fill();ctx.fillStyle='#172033';ctx.font='bold 13px Arial';ctx.fillText(`P${i+1}`,x+10,y-9)})}
 }
 function highlightSelection(){if(selected<0||!points[selected]||!section.open)return;const [x,y]=map(points[selected]);ctx.beginPath();ctx.arc(x,y,12,0,Math.PI*2);ctx.strokeStyle='#cf4d00';ctx.lineWidth=3;ctx.stroke()}
 function changed(record=true){dirty=true;$('revEditorError').textContent='';draw();highlightSelection();table();if(record)commit();else syncHistory()}
 function locate(e){const rect=canvas.getBoundingClientRect();return [e.clientX-rect.left,e.clientY-rect.top]}
 function position(e){let [x,y]=unmap(...locate(e));if($('revSnap').checked){x=Math.round(x*4)/4;y=Math.round(y*4)/4}return [Math.max(-200,Math.min(200,Number(x.toFixed(3)))),Math.max(-200,Math.min(200,Number(y.toFixed(3))))]}
 canvas.addEventListener('pointerdown',e=>{canvas.focus({preventScroll:true});const [x,y]=locate(e),tool=$('revEditorTool').value;if(['pan','axis'].includes(tool)){panStart={x,y,cx:centerX,cy:centerY};canvas.setPointerCapture(e.pointerId);return}drag=points.findIndex(p=>{const q=map(p);return Math.hypot(q[0]-x,q[1]-y)<14});if(drag<0){if(tool==='select'){selected=-1;draw();syncHistory();return}const max=$('revDrawType').value==='bezier'?4:40;if(points.length>=max){$('revEditorError').textContent=`Máximo ${max} puntos para este trazo.`;return}points.push(position(e));drag=points.length-1}selected=drag;changed(false);canvas.setPointerCapture(e.pointerId)});
 canvas.addEventListener('pointermove',e=>{const p=position(e);$('revPointerCoordinates').textContent=`x = ${p[0]} cm; y = ${p[1]} cm`;if(panStart){if($('revEditorTool').value==='pan'){const [x,y]=locate(e);centerX=panStart.cx-(x-panStart.x)*span/(w*.85);centerY=panStart.cy+(y-panStart.y)*span/(w*.85)}else{document.getElementById('revAxisPosition').value=p[0]}draw();return}if(drag>=0){points[drag]=p;changed(false)}});
 const release=()=>{if(panStart&&$('revEditorTool').value==='axis')document.getElementById('revAxisPosition').dispatchEvent(new Event('change'));if(drag>=0)commit();drag=-1;panStart=null};canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
 $('revEditorPoints').addEventListener('change',e=>{const i=Number(e.target.dataset.point),k=Number(e.target.dataset.coordinate),v=Number(e.target.value);if(!Number.isInteger(i)||!points[i]||![0,1].includes(k)||!Number.isFinite(v)||Math.abs(v)>200){$('revEditorError').textContent='Coordenadas entre −200 y 200.';return}points[i][k]=v;changed()});
 $('revEditorPoints').addEventListener('focusin',e=>{if(e.target.dataset.point===undefined)return;selected=Number(e.target.dataset.point);draw();highlightSelection();syncHistory()});
 $('revUndoPoint').addEventListener('click',()=>{if(history.canUndo)restore(history.undo())});$('revRedoPoint').addEventListener('click',()=>{if(history.canRedo)restore(history.redo())});
 function deleteSelected(){if(selected<0||selected>=points.length)return;points.splice(selected,1);selected=-1;changed()}
 $('revDeleteSelected').addEventListener('click',deleteSelected);$('revClearPoints').addEventListener('click',()=>{points=[];selected=-1;changed()});$('revDrawType').addEventListener('change',()=>changed());
 section.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||e.target.isContentEditable)return;const key=e.key.toLowerCase(),modifier=e.ctrlKey||e.metaKey;if(modifier&&(key==='z'||key==='y')){e.preventDefault();const redo=key==='y'||e.shiftKey;if(redo&&history.canRedo)restore(history.redo());else if(!redo&&history.canUndo)restore(history.undo());return}if(e.target!==canvas)return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected()}if(selected>=0&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const step=e.shiftKey?1:.25,axis=['ArrowLeft','ArrowRight'].includes(e.key)?0:1,sign=['ArrowLeft','ArrowDown'].includes(e.key)?-1:1;points[selected][axis]=Math.max(-200,Math.min(200,points[selected][axis]+step*sign));changed()}});
 $('revFitDrawing').addEventListener('click',()=>{if(points.length){const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);centerX=(Math.min(...xs)+Math.max(...xs))/2;centerY=(Math.min(...ys)+Math.max(...ys))/2;span=Math.max(4,Math.max(...xs)-Math.min(...xs),(Math.max(...ys)-Math.min(...ys))*w/h)*1.3}draw()});
 for(const [id,factor] of [['revEditorZoomIn',.8],['revEditorZoomOut',1.25]])$(id).addEventListener('click',()=>{span=Math.max(1,Math.min(800,span*factor));draw()});$('revEditorOrigin').addEventListener('click',()=>{centerX=centerY=0;span=12;draw()});$('revEditorFull').addEventListener('click',()=>document.fullscreenElement?document.exitFullscreen():section.requestFullscreen());canvas.addEventListener('wheel',e=>{e.preventDefault();const pos=locate(e),before=unmap(...pos);span=Math.max(1,Math.min(800,span*(e.deltaY>0?1.12:1/1.12)));const after=unmap(...pos);centerX+=before[0]-after[0];centerY+=before[1]-after[1];draw()},{passive:false});
 $('revApplyDrawing').addEventListener('click',()=>{const kind=$('revDrawType').value;if(points.length<(kind==='custom'?3:2)||kind==='bezier'&&points.length!==4){$('revEditorError').textContent=kind==='bezier'?'Coloca exactamente cuatro controles.':'Añade más puntos para definir la figura.';return}apply(kind,points.map(p=>[...p]));$('revEditorError').textContent='El visor muestra el resultado si el trazo cumple las condiciones indicadas; revisa cualquier aviso de validación.'});
 section.addEventListener('toggle',draw);new ResizeObserver(draw).observe(canvas);
 let lastProfile;
 syncHistory();
 return {refresh:draw,sync(profile){if(dirty||lastProfile===profile)return;lastProfile=profile;const curve=profile.originalCurve||profile.curve;points=curve.filter((_,i)=>i%Math.max(1,Math.floor(curve.length/12))===0).slice(0,40).map(p=>[...p]);history.reset(snapshot());selected=-1;table();draw();syncHistory()}};
}
